// Red-and-black category banners shown at the bottom of the bots' embeds.
// The GIFs live in the dashboard's public/banners folder (generated by
// scripts/generate-banners.py), so a message carries a URL and never uploads
// an attachment. Without a usable SITE_URL the embeds simply have no banner.

export const BANNER_CATEGORIES = Object.freeze([
  "fwu", "communaute", "social", "jeux", "cartes", "tickets", "ia", "evenements",
  "classement", "statistiques", "moderation", "securite", "verification", "verrou",
  "musique", "vocal", "systeme", "roles", "automatisation", "economie", "casino", "boutique",
]);
const KNOWN = new Set(BANNER_CATEGORIES);

/** Slash/prefix command -> banner category. Unlisted commands fall back to "fwu". */
const COMMAND_CATEGORY = Object.freeze({
  niveau: "communaute", suggestion: "communaute", anniversaire: "communaute", rappel: "communaute",
  profil: "communaute", bio: "communaute", sondage: "communaute",
  rep: "social", toprep: "social", afk: "social", story: "social", confession: "social",
  dice: "jeux", coinflip: "jeux", trivia: "jeux", giveaway: "jeux", duel: "jeux", pari: "jeux",
  cards: "cartes", card: "cartes", pack: "cartes", trade: "cartes",
  ticket: "tickets", candidature: "tickets",
  ia: "ia", knowledge: "ia",
  event: "evenements", pndevent: "evenements", live: "evenements", academy: "evenements", award: "evenements",
  leaderboard: "classement", radar: "classement", wrapped: "classement",
  stats: "statistiques", status: "statistiques",
  warn: "moderation", warnings: "moderation", mute: "moderation", unmute: "moderation",
  kick: "moderation", purge: "moderation", ban: "moderation", blacklist: "moderation",
  casier: "moderation", nettoyer: "moderation", slowmode: "moderation",
  guildguard: "securite", antinuke: "securite", automod: "securite", quarantaine: "securite",
  verify: "verification",
  lock: "verrou", unlock: "verrou", lockname: "verrou", menotte: "verrou", unmenotte: "verrou",
  menotteinfo: "verrou", dog: "verrou", undog: "verrou", doginfo: "verrou", undogall: "verrou",
  wouaf: "verrou", "anti-moove": "verrou",
  play: "musique", pause: "musique", resume: "musique", skip: "musique", stop: "musique",
  queue: "musique", nowplaying: "musique", volume: "musique", loop: "musique", shuffle: "musique",
  clearqueue: "musique", remove: "musique", musicpanel: "musique", radio: "musique",
  effet: "musique", playlist: "musique", dj: "musique",
  join: "vocal", leave: "vocal", pv: "vocal", voc: "vocal", access: "vocal", unaccess: "vocal",
  vocalpresence: "vocal", wakeup: "vocal",
  sysp: "systeme", panel: "systeme", setup: "systeme", maj: "systeme", webhook: "systeme",
  staff: "systeme", staffhistory: "systeme", aide: "systeme",
  rank: "roles", rankall: "roles", removerole: "roles", rolepanel: "roles", roletemp: "roles",
  color: "roles", pseudo: "roles", annonce: "roles", dmall: "roles",
  automation: "automatisation",
  balance: "economie", daily: "economie", work: "economie", job: "economie", bank: "economie",
  history: "economie", rob: "economie", lottery: "economie", pay: "economie", pnd: "economie",
  impots: "economie", pret: "economie", business: "economie", invest: "economie",
  casino: "casino", roulette: "casino", blackjack: "casino", mines: "casino", crash: "casino",
  shop: "boutique", buy: "boutique", inventory: "boutique",
});

export function categoryForCommand(name) {
  const key = String(name ?? "").trim().toLowerCase();
  return COMMAND_CATEGORY[key] ?? null;
}

/** HTTPS URL of a category banner, or null when SITE_URL is missing or unusable. */
export function bannerUrl(category) {
  const key = String(category ?? "").trim().toLowerCase();
  if (!KNOWN.has(key)) return null;
  const base = process.env.SITE_URL?.trim();
  if (!base) return null;
  try {
    const site = new URL(base);
    if (site.protocol !== "https:" && site.hostname !== "localhost" && site.hostname !== "127.0.0.1") return null;
    return new URL(`/banners/${key}.gif`, site).toString();
  } catch {
    return null;
  }
}

const hasImage = (embed) => Boolean(embed?.image?.url ?? embed?.data?.image?.url);

/** Sets the banner on one embed (plain object or EmbedBuilder) unless it already shows an image. */
export function applyBanner(embed, category) {
  const url = bannerUrl(category);
  if (!url || !embed || hasImage(embed)) return embed;
  if (typeof embed.setImage === "function") embed.setImage(url);
  else embed.image = { url };
  return embed;
}

/**
 * Banners every embed of an interaction payload. Embeds that already carry an
 * image (live alerts, cards, profile pictures) are left untouched.
 */
export function applyBannerToPayload(payload, category) {
  if (!payload || typeof payload !== "object" || !Array.isArray(payload.embeds) || !payload.embeds.length) return payload;
  if (!bannerUrl(category)) return payload;
  for (const embed of payload.embeds) applyBanner(embed, category);
  return payload;
}
